export function parseTransaction(transaction, wallet) {
      if (!transaction?.meta) {
          return {
                type: "OTHER",
                      reason: "Missing transaction metadata",
                            tokenChanges: [],
                                  solChange: null,
                                        trade: null
                                            };
                                              }

                                                const meta = transaction.meta;

                                                  const preBalances =
                                                      meta.preTokenBalances || [];

                                                        const postBalances =
                                                            meta.postTokenBalances || [];

                                                              const tokenChanges = [];

                                                                const allMints = new Set([
                                                                    ...preBalances.map((x) => x.mint),
                                                                        ...postBalances.map((x) => x.mint)
                                                                          ]);

                                                                            for (const mint of allMints) {
                                                                                const pre = preBalances.filter(
                                                                                      (x) =>
                                                                                              x.mint === mint &&
                                                                                                      x.owner === wallet
                                                                                                          );

                                                                                                              const post = postBalances.filter(
                                                                                                                    (x) =>
                                                                                                                            x.mint === mint &&
                                                                                                                                    x.owner === wallet
                                                                                                                                        );

                                                                                                                                            const before = pre.reduce(
                                                                                                                                                  (total, item) =>
                                                                                                                                                          total +
                                                                                                                                                                  BigInt(
                                                                                                                                                                            item.uiTokenAmount?.amount || "0"
                                                                                                                                                                                    ),
                                                                                                                                                                                          0n
                                                                                                                                                                                              );

                                                                                                                                                                                                  const after = post.reduce(
                                                                                                                                                                                                        (total, item) =>
                                                                                                                                                                                                                total +
                                                                                                                                                                                                                        BigInt(
                                                                                                                                                                                                                                  item.uiTokenAmount?.amount || "0"
                                                                                                                                                                                                                                          ),
                                                                                                                                                                                                                                                0n
                                                                                                                                                                                                                                                    );

                                                                                                                                                                                                                                                        const change = after - before;

                                                                                                                                                                                                                                                            if (change === 0n) {
                                                                                                                                                                                                                                                                  continue;
                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                          const decimals =
                                                                                                                                                                                                                                                                                post[0]?.uiTokenAmount?.decimals ??
                                                                                                                                                                                                                                                                                      pre[0]?.uiTokenAmount?.decimals ??
                                                                                                                                                                                                                                                                                            0;

                                                                                                                                                                                                                                                                                                tokenChanges.push({
                                                                                                                                                                                                                                                                                                      mint,
                                                                                                                                                                                                                                                                                                            rawChange: change.toString(),
                                                                                                                                                                                                                                                                                                                  decimals,
                                                                                                                                                                                                                                                                                                                        direction:
                                                                                                                                                                                                                                                                                                                                change > 0n
                                                                                                                                                                                                                                                                                                                                          ? "IN"
                                                                                                                                                                                                                                                                                                                                                    : "OUT"
                                                                                                                                                                                                                                                                                                                                                        });
                                                                                                                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                                                                                                                            /*
                                                                                                                                                                                                                                                                                                                                                               * SOL BALANCE
                                                                                                                                                                                                                                                                                                                                                                  */

                                                                                                                                                                                                                                                                                                                                                                    const accountKeys =
                                                                                                                                                                                                                                                                                                                                                                        transaction.transaction?.message?.accountKeys || [];

                                                                                                                                                                                                                                                                                                                                                                          const walletIndex =
                                                                                                                                                                                                                                                                                                                                                                              accountKeys.findIndex(
                                                                                                                                                                                                                                                                                                                                                                                    (key) =>
                                                                                                                                                                                                                                                                                                                                                                                            key === wallet ||
                                                                                                                                                                                                                                                                                                                                                                                                    key?.pubkey === wallet
                                                                                                                                                                                                                                                                                                                                                                                                        );

                                                                                                                                                                                                                                                                                                                                                                                                          let solChange = null;

                                                                                                                                                                                                                                                                                                                                                                                                            if (
                                                                                                                                                                                                                                                                                                                                                                                                                walletIndex >= 0 &&
                                                                                                                                                                                                                                                                                                                                                                                                                    meta.preBalances &&
                                                                                                                                                                                                                                                                                                                                                                                                                        meta.postBalances
                                                                                                                                                                                                                                                                                                                                                                                                                          ) {
                                                                                                                                                                                                                                                                                                                                                                                                                              const before =
                                                                                                                                                                                                                                                                                                                                                                                                                                    BigInt(
                                                                                                                                                                                                                                                                                                                                                                                                                                            meta.preBalances[walletIndex] || 0
                                                                                                                                                                                                                                                                                                                                                                                                                                                  );

                                                                                                                                                                                                                                                                                                                                                                                                                                                      const after =
                                                                                                                                                                                                                                                                                                                                                                                                                                                            BigInt(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    meta.postBalances[walletIndex] || 0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                          );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const change = after - before;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  solChange = {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        rawChange: change.toString(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              solChange:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      Number(change) / 1_000_000_000,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            direction:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    change > 0n
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ? "IN"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        : change < 0n
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ? "OUT"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                : "NONE"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        /*
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           * CLASSIFY TRANSACTION
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              */

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const tokenIn =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    tokenChanges.filter(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          (x) => x.direction === "IN"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const tokenOut =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    tokenChanges.filter(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          (x) => x.direction === "OUT"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const solAmount =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    Math.abs(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          solChange?.solChange || 0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const meaningfulSol =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    solAmount > 0.0005;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      let type = "OTHER";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        let reason =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            "No trade pattern detected";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              /*
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 * BUY
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    *
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       * Token enters wallet
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          * SOL leaves wallet
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             */

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               if (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   tokenIn.length > 0 &&
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       solChange?.direction === "OUT" &&
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           meaningfulSol
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             ) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 type = "BUY";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     reason =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           "Tokens received while SOL left wallet";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               /*
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  * SELL
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     *
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        * Token leaves wallet
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           * SOL enters wallet
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              */

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                else if (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    tokenOut.length > 0 &&
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        solChange?.direction === "IN" &&
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            meaningfulSol
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  type = "SELL";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      reason =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            "Tokens sent while SOL entered wallet";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                /*
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   * TOKEN TRANSFER
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      */

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        else if (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            tokenIn.length > 0 &&
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                !meaningfulSol
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      type = "TRANSFER_IN";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          reason =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                "Tokens received without significant SOL payment";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    else if (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        tokenOut.length > 0 &&
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            !meaningfulSol
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  type = "TRANSFER_OUT";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      reason =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            "Tokens sent without significant SOL receipt";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                /*
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   * SOL TRANSFER
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      */

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        else if (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            meaningfulSol &&
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                tokenChanges.length === 0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      type = "SOL_TRANSFER";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          reason =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                "SOL balance changed without token movement";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    /*
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       * TRADE OBJECT
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          */

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            let trade = null;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  (type === "BUY" || type === "SELL") &&
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      tokenChanges.length === 1 &&
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          solChange
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const token =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      tokenChanges[0];

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const tokenAmount =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                Math.abs(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        Number(token.rawChange)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ) /
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    10 ** token.decimals;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const solAmountAbs =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              Math.abs(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      solChange.solChange
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const price =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      tokenAmount > 0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ? solAmountAbs / tokenAmount
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      : null;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          trade = {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                wallet,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      type,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            tokenMint: token.mint,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  tokenAmount,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        solAmount: solAmountAbs,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              estimatedPriceSol: price
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      return {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          type,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              reason,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  tokenChanges,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      solChange,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          trade
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }